<script setup lang="ts">
import { computed, ref } from 'vue';
import { activityStats, inPeriod, periodLabel, type StudentCourse } from '../student-pages';
const props=defineProps<{course:StudentCourse;classroomLabel?:string;confirmedAt?:string}>();
const emit=defineEmits<{updateProgress:[];resume:[id:string];history:[id:string];startAction:[text:string];showStatus:[chapter:string];showTextbook:[];openQuestions:[filter:string];openActivity:[id:string]}>();
const days=ref(7),history=ref(false),kind=ref('全部'),dismissed=ref(false),showDates=ref(false);
const stats=computed(()=>activityStats(props.course,days.value));
const recent=computed(()=>props.course.activities[0]);
const next=computed(()=>props.course.chapters.find(c=>c.requirements.some(r=>r.status==='需加强')&&!(recent.value&&!recent.value.finished&&recent.value.chapterId===c.id)));
const records=computed(()=>kind.value==='讲解'?stats.value.lectures:kind.value==='检测'?stats.value.tests:props.course.activities.filter(a=>inPeriod(a.at,days.value,props.course.asOf)));
function openHistory(filter='全部'){history.value=true;kind.value=filter;}
</script>
<template><div class="student-page home-page">
  <header class="page-header"><div><h2>{{history?'学习记录':'首页'}}</h2><p class="muted">{{course.title}}</p></div><div v-if="!history" class="time"><strong>今日用时 {{course.todayMinutes===undefined?'尚未统计':course.todayMinutes+' 分钟（示例）'}}</strong><span class="tiny">全部空间合计 · 每日总投入不超过 30 分钟</span></div></header>
  <template v-if="!history">
    <section class="panel accent classroom-progress"><div class="row"><div><p class="tiny">学校正在学</p><h3>{{classroomLabel||'学校学到哪了？'}}</h3><p class="tiny">{{confirmedAt?'上次确认：'+confirmedAt.slice(0,10):'尚未填写，可以随时更新'}}</p></div><button @click="emit('updateProgress')">更新课堂进度</button></div></section>
    <section class="panel continue-learning"><template v-if="recent"><p class="tiny">{{recent.finished?'上次学习':'继续学习'}}</p><h3>{{recent.title}}</h3><p class="muted">{{recent.detail}}</p><div class="row"><button class="primary" @click="recent.finished ? emit('history',recent.id) : emit('resume',recent.id)">{{recent.finished?'回看这次学习':'继续学习'}}</button><div class="actions"><button class="link" @click="emit('showStatus',recent.chapterId)">本章学习情况 →</button><button class="link" @click="openHistory()">全部学习记录 →</button></div></div></template><template v-else><h3>从你想学的内容开始</h3><p class="muted">可以先找一章，也可以在下方直接提问。</p><button class="primary" @click="emit('showTextbook')">去教材选择内容</button></template></section>
    <section v-if="next&&!dismissed" class="panel suggestion"><div class="row"><h3>也可以试试</h3><button class="link" @click="dismissed=true">暂时忽略</button></div><p>{{next.requirements.find(r=>r.status==='需加强')?.reason}}</p><p class="muted">先讲清一个关键问题，再由你决定是否继续。</p><div class="actions"><button @click="emit('startAction','请围绕“'+next.name+'”讲解：'+next.requirements.find(r=>r.status==='需加强')?.name)">讲讲这里</button><button class="link" @click="emit('showStatus',next.id)">查看本章学习情况 →</button></div></section>
    <section class="panel"><div class="row"><h3>近期学习</h3><label>统计范围<select aria-label="统计范围" v-model.number="days"><option :value="7">近 7 天</option><option :value="30">近 30 天</option></select></label></div><p class="tiny">{{periodLabel(days,course.asOf)}}</p><div class="stats-grid"><button class="stat" @click="showDates=true"><strong>{{stats.dates.length}} <small>天</small></strong><span>开展过学习</span></button><button class="stat" @click="openHistory('讲解')"><strong>{{stats.lectures.length}} <small>次</small></strong><span>开展讲解</span></button><button class="stat" @click="openHistory('检测')"><strong>{{stats.tests.length}} <small>次</small></strong><span>已结束检测</span></button></div><div class="row"><button class="link" @click="emit('openQuestions','wrong')">当前错题 {{stats.wrong.length}} 道 →</button><span class="tiny">全部日期中的现有记录，含后来订正的题</span></div><details><summary>这些数字怎么算？</summary><p class="muted">当天实际看过讲解、开始检测或提交作答才计入学习天数。同一次讲解继续多天只计一次讲解。检测至少提交过一次作答且已经结束才计入，中途结束会单独标明。同一道题多次答错只计一道，订正不删除历史错误。</p></details></section>
  </template>
  <template v-else><button class="back" @click="history=false">← 返回首页</button><div class="controls"><label>活动类型<select aria-label="活动类型" v-model="kind"><option>全部</option><option>讲解</option><option>检测</option></select></label><label>统计范围<select aria-label="统计范围" v-model.number="days"><option :value="7">近 7 天</option><option :value="30">近 30 天</option><option :value="0">全部</option></select></label></div><p class="tiny">{{periodLabel(days,course.asOf)}}</p><section class="panel"><article v-for="a in records" :key="a.id" class="list-row"><div class="tags"><span class="badge">{{a.kind}}</span><span class="tiny">{{a.at}} · {{a.finished?(a.partial?'中途结束':'已结束'):'进行中'}}</span></div><h4>{{a.title}}</h4><p class="muted">{{a.detail}}</p><button @click="emit('openActivity',a.id)">查看学习记录</button></article><p v-if="!records.length" class="empty">这段时间没有符合条件的学习记录。</p></section></template>
  <p class="tiny">{{course.note}}</p>
  <div v-if="showDates" class="modal-shade" @click.self="showDates=false"><section role="dialog" aria-modal="true" aria-label="学习日期" class="modal"><header class="row"><h3>开展过学习的日期</h3><button @click="showDates=false">关闭</button></header><p>{{periodLabel(days,course.asOf)}} · {{stats.dates.length}} 天</p><p v-for="date in stats.dates" :key="date">{{date}}</p><p v-if="!stats.dates.length">暂无符合条件的学习记录。</p></section></div>
</div></template>
